---OnClickTabToggleAction
---过滤下数据
---@param openType number
function UIActivitySkinShopDialog:OnClickTabToggleAction(openType)
    if self.curType == openType then return end
    self.curType = openType
    local t = {}
    for i, v in pairs(self._shopProductData) do
        if checkNumber(v.tab) == checkNumber(openType) then
            table.insert(t, v)
        end
    end
    self.data = t
    self:FillShopInfo()
end

function UIActivitySkinShopDialog:Refresh(activityUuid)
    self._curUuid = checkNumber(activityUuid)

    self:InitData()
    self:InitializeToggle()
    self:FillSelf()
    self:StartTimeDown()
end

function UIActivitySkinShopDialog:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id, countElapsed)
        self:FillTime()
        if self._shopProductData then
            local hasRequest = false
            for i, v in pairs(self._shopProductData) do
                if checkNumber(v.endTime) > 0 then
                    v.endTime = checkNumber(v.endTime) - countElapsed
                    if checkNumber(v.endTime) <= 0 then
                        hasRequest = true
                    end
                end
            end
            if hasRequest then
                GameUtils.Request(Interfaces.StoreActivityHome, {activityUuid = self._curUuid, activityType = self.activityType}, function(request, response)
                    if checkNumber(response.errCode) == 0 then
                        local jsonData = response.data
                        self._shopData =  checkTable(jsonData)
                        self.curType = 0
                        self:Refresh(self._curUuid)
                    end
                end)
            else
                Events.Broadcast("SKIN_SHOP_TIME_COUNT_DOWN")
            end
        end
    end, CountDownTime, false, true)
end

function UIActivitySkinShopDialog:InitData()
    local t = self:GetShopData()
    self._shopProductData = checkTable(t.products)
end

